def min_capacity(workloads, days):
    if not workloads:
        return 0

    def days_needed(capacity):
        used, load = 1, 0
        for w in workloads:
            if load + w > capacity:     # today is full; start tomorrow
                used += 1
                load = 0
            load += w
        return used

    lo = max(workloads)                 # a submission cannot be split
    hi = sum(workloads)                 # one day, everything
    while lo < hi:                      # smallest-feasible template
        mid = (lo + hi) // 2
        if days_needed(mid) <= days:
            hi = mid                    # mid works; it is still a candidate
        else:
            lo = mid + 1                # mid does not; exclude it
    return lo

