javascript.solution:
function minCapacity(workloads, days) {
  if (workloads.length === 0) return 0;

  const daysNeeded = (capacity) => {
    let used = 1;
    let load = 0;
    for (const w of workloads) {
      if (load + w > capacity) {        // today is full; start tomorrow
        used++;
        load = 0;
      }
      load += w;
    }
    return used;
  };

  let lo = Math.max(...workloads);      // a submission cannot be split
  let hi = workloads.reduce((a, w) => a + w, 0);   // one day, everything
  while (lo < hi) {                     // smallest-feasible template
    const mid = Math.floor((lo + hi) / 2);
    if (daysNeeded(mid) <= days) hi = mid;         // still a candidate
    else lo = mid + 1;                             // definitely not
  }
  return lo;
}
